def majority(xs: list[int]) -> int | None:
    """Return the value occurring in more than half of the positions of xs,
or None if no value does.
pre: True
post: __return__ is None or xs.count(__return__) * 2 > len(xs)
post: __return__ is not None or all(xs.count(x) * 2 <= len(xs) for x in xs)
post: len(xs) > 0 or __return__ is None"""
    n = len(xs)
    if n == 0:
        return None
    candidate = None
    count = 0
    for x in xs:
        if count == 0:
            candidate = x
            count = 1
        elif x == candidate:
            count += 1
        else:
            count -= 1
    if candidate is not None and xs.count(candidate) * 2 > n:
        return candidate
    return None

